import { Coordinates, AnalysisResult } from "../types";

/**
 * Deterministic political analysis engine (No AI)
 * Analyzes X (Economic), Y (National Security), and Z (Conservatism)
 */
export const analyzeResults = async (coords: Coordinates): Promise<AnalysisResult> => {
  // Artificial delay to simulate "processing" for better UX
  await new Promise(resolve => setTimeout(resolve, 1500));

  const { x, y, z } = coords;

  // 1. Determine Identity Title & Description
  let title = "";
  let description = "";

  // Quadrant Logic (X, Y)
  const isRight = x >= 0;
  const isHawk = y >= 0;
  const isConservative = z >= 0;

  // Identity logic
  if (isRight) {
    if (isHawk) {
      title = isConservative ? "ימין לאומי-שמרני" : "ימין לאומי-ליברלי";
      description = "אתה דוגל בשוק חופשי, ריבונות מלאה ביהודה ושומרון וגישה ביטחונית תקיפה.";
    } else {
      title = isConservative ? "מרכז-ימין שמרני" : "ליברטריאניזם / ימין ליברלי";
      description = "החופש הכלכלי והאישי עומדים בראש סדר העדיפויות שלך, לצד גישה מדינית פרגמטית.";
    }
  } else {
    if (isHawk) {
      title = isConservative ? "שמאל ביטחוני-שמרני" : "שמאל ביטחוני-ליברלי";
      description = "אתה תומך במדינת רווחה חזקה ובמעורבות ממשלתית, אך מחזיק בעמדות ניציות בנושאי ביטחון.";
    } else {
      title = isConservative ? "שמאל חברתי-מסורתי" : "שמאל ליברלי / סוציאל-דמוקרטיה";
      description = "השקפת עולמך מתמקדת בצמצום פערים חברתיים, פשרה מדינית וקידום ערכים אוניברסליים.";
    }
  }

  // 2. Economic Analysis (X)
  let economicAnalysis = "";
  if (x > 5) {
    economicAnalysis = "קפיטליזם טהור: תמיכה מוחלטת בשוק חופשי, הפרטה רחבה, וצמצום מקסימלי של המעורבות הממשלתית והבירוקרטיה.";
  } else if (x >= 0) {
    economicAnalysis = "כלכלה חופשית: העדפה ליוזמה פרטית והורדת מיסים, תוך הכרה בצורך ברשת ביטחון בסיסית.";
  } else if (x > -5) {
    economicAnalysis = "מדינת רווחה: תמיכה בחיזוק השירותים הציבוריים, הגנת עובדים וצמצום פערים באמצעות מיסוי פרוגרסיבי.";
  } else {
    economicAnalysis = "סוציאליזם חברתי: דרישה למעורבות ממשלתית עמוקה, הלאמת משאבים, וחיזוק דרמטי של ועדי העובדים והקצבאות.";
  }

  // 3. National Security Analysis (Y)
  let nationalAnalysis = "";
  if (y > 5) {
    nationalAnalysis = "ניציות מובהקת: תמיכה בסיפוח, התיישבות רחבה, והכרעה צבאית ללא פשרות מדיניות.";
  } else if (y >= 0) {
    nationalAnalysis = "גישה לאומית: דגש על אינטרסים ביטחוניים, חשדנות כלפי פתרונות מדיניים ושימור הסטטוס קוו הביטחוני.";
  } else if (y > -5) {
    nationalAnalysis = "פרגמטיזם מדיני: נכונות לפשרות טריטוריאליות תמורת ביטחון ושלום, תוך דגש על לגיטימציה בינלאומית.";
  } else {
    nationalAnalysis = "יוניות ליברלית: תמיכה בפתרון שתי המדינות, סיום השליטה ביהודה ושומרון וקידום זכויות אדם כערך עליון.";
  }

  // 4. Religious & Social Analysis (Z)
  let religiousAnalysis = "";
  if (z > 5) {
    religiousAnalysis = "שמרנות דתית: תמיכה בחיזוק הזהות היהודית של המדינה, שמירה על הסטטוס קוו והעדפת ערכי המסורת והמשפחה.";
  } else if (z >= 0) {
    religiousAnalysis = "מסורתיות מתונה: כבוד למורשת ישראל ולערכים שמרניים, תוך שילובם בחיים המודרניים ללא כפייה קיצונית.";
  } else if (z > -5) {
    religiousAnalysis = "ליברליות חילונית: תמיכה בהפרדת דת ומדינה, חופש דת וחופש מדת, וקידום זכויות לקהילת הלהט\"ב.";
  } else {
    religiousAnalysis = "פרוגרסיביות: דרישה לשינוי רדיקלי ביחסי דת ומדינה, שוויון מלא ומגדרי מוחלט וביטול מוסדות הדת הממלכתיים.";
  }

  return {
    title,
    description,
    ideology: "", // Legacy field
    economicAnalysis,
    nationalAnalysis,
    religiousAnalysis
  };
};

