import React, { useEffect, useState, useRef } from 'react';
import { Coordinates, AnalysisResult, Answer } from '../types';
import CompassChart from './CompassChart';
import { analyzeResults } from '../services/geminiService';
import { reportResult } from '../services/reportingService';
import { RefreshCw, Sparkles, Share2, Check, Download, Compass, Wallet, Shield, ScrollText, RotateCcw } from 'lucide-react';
import html2canvas from 'html2canvas';

interface ResultViewProps {
  coordinates: Coordinates;
  compareCoordinates?: Coordinates | null;
  onRetake: () => void;
  initialAnalysis?: AnalysisResult | null;
  onAnalysisComplete?: (analysis: AnalysisResult) => void;
  isDarkMode?: boolean;
  isAccessible?: boolean;
  quizDuration?: number;
  answers?: Answer[];
  userName?: string;
  userEmail?: string;
  friendName?: string;
}

const ResultView: React.FC<ResultViewProps> = ({ 
  coordinates, 
  compareCoordinates,
  onRetake, 
  initialAnalysis = null, 
  onAnalysisComplete,
  isDarkMode = false,
  isAccessible = false,
  quizDuration = 0,
  answers = [],
  userName = "אני",
  userEmail = "",
  friendName
}) => {
  const [analysis, setAnalysis] = useState<AnalysisResult | null>(initialAnalysis);
  const [loading, setLoading] = useState(!initialAnalysis);
  const [copied, setCopied] = useState(false);
  const [downloading, setDownloading] = useState(false);

  const resultRef = useRef<HTMLDivElement>(null);
  const hasReportedRef = useRef(false);

  useEffect(() => {
    if (initialAnalysis) {
      setAnalysis(initialAnalysis);
      setLoading(false);
      return;
    }

    let isMounted = true;
    const fetchAnalysis = async () => {
      setLoading(true);
      const result = await analyzeResults(coordinates);

      if (isMounted) {
        setAnalysis(result);
        setLoading(false);
        if (onAnalysisComplete) {
          onAnalysisComplete(result);
        }

        if (!hasReportedRef.current) {
            hasReportedRef.current = true;
            reportResult(coordinates, result, {
              duration: quizDuration,
              answers: answers,
              userName: userName || "Anonymous",
              userEmail: userEmail || "",
              comparedWith: friendName
            });
        }
      }
    };
    fetchAnalysis();
    return () => { isMounted = false; };
  }, [coordinates, initialAnalysis]);

  const handleShare = async () => {
    if (!analysis) return;

    const nameForShare = userName && userName !== "אני" ? userName : "מישהו";
    const params = new URLSearchParams();
    params.set('x', coordinates.x.toString());
    params.set('y', coordinates.y.toString());
    params.set('z', coordinates.z.toString());
    params.set('title', encodeURIComponent(analysis.title));
    params.set('desc', encodeURIComponent(analysis.description));
    params.set('name', encodeURIComponent(nameForShare));

    const shareUrl = `${window.location.origin}${window.location.pathname}?${params.toString()}`;
    const text = `התוצאה של ${nameForShare} במצפן הפוליטי: ${analysis.title}. בואו לגלות את הזהות הפוליטית שלכם:`;

    if (navigator.share) {
      try {
        await navigator.share({
          title: 'המצפן הפוליטי',
          text: text,
          url: shareUrl
        });
      } catch (err) {
        console.log('Error sharing:', err);
      }
    } else {
      try {
        await navigator.clipboard.writeText(`${text}\n${shareUrl}`);
        setCopied(true);
        setTimeout(() => setCopied(false), 2000);
      } catch (err) {
        console.error('Failed to copy:', err);
      }
    }
  };

  const handleDownload = async () => {
    if (!resultRef.current || downloading) return;

    setDownloading(true);
    try {
      const canvas = await html2canvas(resultRef.current, {
        backgroundColor: isDarkMode ? '#0f172a' : '#ffffff',
        scale: 2,
        useCORS: true,
        logging: false
      });

      const link = document.createElement('a');
      link.download = `political-compass-${userName || 'result'}.png`;
      link.href = canvas.toDataURL('image/png');
      link.click();
    } catch (err) {
      console.error('Download failed:', err);
    } finally {
      setDownloading(false);
    }
  };

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center py-24 space-y-6">
        <div className="relative">
          <RefreshCw className="w-16 h-16 text-yellow-500 animate-spin" />
          <Sparkles className="absolute -top-2 -right-2 w-6 h-6 text-yellow-400 animate-pulse" />
        </div>
        <div className="text-center px-4">
          <h3 className="text-2xl font-black text-slate-900 dark:text-white mb-2">מנתח את הנתונים...</h3>
          <p className="text-slate-500 dark:text-slate-400 font-medium">המערכת מעבדת את התשובות שלך ובונה פרופיל פוליטי מדויק</p>
        </div>
      </div>
    );
  }

  return (
    <div className="w-full max-w-5xl mx-auto px-4 pb-20 animate-fadeIn" dir="rtl">
      <div ref={resultRef} className="bg-white dark:bg-slate-900 rounded-[2.5rem] shadow-2xl border border-slate-200 dark:border-slate-800 overflow-hidden mb-8 transition-colors duration-300">
        <div className="p-8 md:p-12">
          <div className="text-center mb-12">
            <h2 className="text-4xl md:text-5xl font-black text-slate-900 dark:text-white mb-4 leading-tight">
              {userName && userName !== "אני" ? `${userName}, אתה: ` : 'הזהות הפוליטית שלך: '}
              <span className="text-transparent bg-clip-text bg-gradient-to-r from-yellow-500 to-yellow-600 dark:from-yellow-200 dark:to-yellow-500">
                {analysis?.title}
              </span>
            </h2>
            <p className="text-xl text-slate-600 dark:text-slate-400 font-medium max-w-2xl mx-auto leading-relaxed">
              {analysis?.description}
            </p>
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-2 gap-12 items-start">
            <div className="bg-slate-50 dark:bg-slate-800/50 p-6 md:p-8 rounded-3xl border border-slate-100 dark:border-slate-700 shadow-inner">
              <CompassChart 
                coordinates={coordinates} 
                compareCoordinates={compareCoordinates}
                userName={userName}
                friendName={friendName}
                isDarkMode={isDarkMode}
                isAccessible={isAccessible}
              />
            </div>

            <div className="space-y-6">
              <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl border border-slate-100 dark:border-slate-700 shadow-sm flex gap-4">
                <div className="bg-green-100 dark:bg-green-900/30 p-3 h-fit rounded-xl">
                  <Wallet className="w-6 h-6 text-green-600 dark:text-green-400" />
                </div>
                <div>
                  <h4 className="font-black text-slate-900 dark:text-white mb-1">כלכלה וחברה</h4>
                  <p className="text-slate-600 dark:text-slate-400 leading-relaxed text-sm md:text-base">{analysis?.economicAnalysis}</p>
                </div>
              </div>

              <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl border border-slate-100 dark:border-slate-700 shadow-sm flex gap-4">
                <div className="bg-blue-100 dark:bg-blue-900/30 p-3 h-fit rounded-xl">
                  <Shield className="w-6 h-6 text-blue-600 dark:text-blue-400" />
                </div>
                <div>
                  <h4 className="font-black text-slate-900 dark:text-white mb-1">ביטחון ולאומיות</h4>
                  <p className="text-slate-600 dark:text-slate-400 leading-relaxed text-sm md:text-base">{analysis?.nationalAnalysis}</p>
                </div>
              </div>

              <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl border border-slate-100 dark:border-slate-700 shadow-sm flex gap-4">
                <div className="bg-purple-100 dark:bg-purple-900/30 p-3 h-fit rounded-xl">
                  <ScrollText className="w-6 h-6 text-purple-600 dark:text-purple-400" />
                </div>
                <div>
                  <h4 className="font-black text-slate-900 dark:text-white mb-1">זהות ומסורת</h4>
                  <p className="text-slate-600 dark:text-slate-400 leading-relaxed text-sm md:text-base">{analysis?.religiousAnalysis}</p>
                </div>
              </div>
            </div>
          </div>
        </div>

        <div className="bg-slate-50 dark:bg-slate-800 border-t border-slate-200 dark:border-slate-700 px-8 py-4 flex justify-between items-center">
           <div className="flex items-center gap-2">
              <Compass className="w-5 h-5 text-yellow-500" />
              <span className="font-black text-slate-900 dark:text-white text-sm">המצפן הפוליטי | פרוייקט דעת</span>
           </div>
           <span className="text-xs text-slate-400 font-bold">www.projectdaat.co.il</span>
        </div>
      </div>

      <div className="flex flex-wrap justify-center gap-4">
        <button 
          onClick={handleShare}
          className="flex items-center gap-2 px-8 py-4 bg-yellow-400 text-slate-950 font-black rounded-2xl hover:bg-yellow-300 transition-all hover:-translate-y-1 shadow-lg active:scale-95"
        >
          {copied ? <Check className="w-5 h-5" /> : <Share2 className="w-5 h-5" />}
          <span>{copied ? 'הקישור הועתק!' : 'שתף תוצאה'}</span>
        </button>

        <button 
          onClick={handleDownload}
          disabled={downloading}
          className="flex items-center gap-2 px-8 py-4 bg-white dark:bg-slate-800 text-slate-700 dark:text-slate-300 font-bold rounded-2xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-slate-700 transition-all hover:-translate-y-1 shadow-md active:scale-95"
        >
          {downloading ? <RefreshCw className="w-5 h-5 animate-spin" /> : <Download className="w-5 h-5" />}
          <span>הורד כתמונה</span>
        </button>

        <button 
          onClick={onRetake}
          className="flex items-center gap-2 px-8 py-4 bg-slate-900 dark:bg-slate-100 text-white dark:text-slate-900 font-bold rounded-2xl hover:bg-slate-800 dark:hover:bg-white transition-all hover:-translate-y-1 shadow-lg active:scale-95"
        >
          <RotateCcw className="w-5 h-5" />
          <span>בצע מבחן חדש</span>
        </button>
      </div>
    </div>
  );
};

