                {/* Quadrants background - Rendered first */}
                <ReferenceArea x1={-10} x2={0} y1={0} y2={10} fill={colors.authLeft} fillOpacity={opacity} stroke="none" isFront={false} />
                <ReferenceArea x1={0} x2={10} y1={0} y2={10} fill={colors.authRight} fillOpacity={opacity} stroke="none" isFront={false} />
                <ReferenceArea x1={-10} x2={0} y1={-10} y2={0} fill={colors.libLeft} fillOpacity={opacity} stroke="none" isFront={false} />
                <ReferenceArea x1={0} x2={10} y1={-10} y2={0} fill={colors.libRight} fillOpacity={opacity} stroke="none" isFront={false} />

                {/* Gridlines */}
                <CartesianGrid stroke={colors.grid} strokeDasharray="3 3" strokeOpacity={0.3} />

                {/* Axes */}
                <ReferenceLine x={0} stroke={colors.axis} strokeWidth={2} />
                <ReferenceLine y={0} stroke={colors.axis} strokeWidth={2} />

                {/* Friend Marker */}
                {compareData.length > 0 && (
                     <Scatter name={friendName} data={compareData} isAnimationActive={false}>
                        <Cell 
                          fill="#475569" 
                          stroke="white" 
                          strokeWidth={2} 
                          r={8} 
                        />
                        <LabelList 
                            dataKey="name" 
                            position="top" 
                            offset={10} 
                            style={{ 
                                fill: isDarkMode ? '#f1f5f9' : '#0f172a', 
                                fontWeight: '800', 
                                fontSize: '11px',
                                paintOrder: 'stroke',
                                stroke: isDarkMode ? '#0f172a' : '#ffffff',
                                strokeWidth: '3px'
                            }} 
                        />
                     </Scatter>
                )}

                {/* User Marker */}
                <Scatter name={userName} data={userData} isAnimationActive={false}>
                  <Cell 
                    fill="#dc2626" 
                    stroke="#ffffff" 
                    strokeWidth={3} 
                    r={12} 
                    className="filter drop-shadow-[0_0_8px_rgba(220,38,38,0.6)]"
                  />
                  <LabelList 
                    dataKey="name" 
                    position="top" 
                    offset={12} 
                    style={{ 
                        fill: isDarkMode ? '#f1f5f9' : '#0f172a', 
                        fontWeight: '900', 
                        fontSize: '13px',
                        paintOrder: 'stroke',
                        stroke: isDarkMode ? '#0f172a' : '#ffffff',
                        strokeWidth: '4px'
                    }} 
                  />
                </Scatter>
              </ScatterChart>
            </ResponsiveContainer>
        </div>
      </div>

      {/* Conservatism Z-Axis */}
      <div className="w-full max-w-lg px-4 mt-8 space-y-3">
        <div className="flex justify-between items-end mb-1">
            <span className="text-sm font-black text-slate-700 dark:text-slate-300">שמרנות (זהות ומסורת)</span>
            <span className={`text-lg font-black ${safeCoords.z > 0 ? 'text-blue-600 dark:text-blue-400' : 'text-pink-600 dark:text-pink-400'}`}>
                {safeCoords.z > 0 ? 'שמרן' : 'פרוגרסיבי'} ({Math.abs(safeCoords.z).toFixed(1)})
            </span>
        </div>
        <div className="h-6 w-full bg-slate-200 dark:bg-slate-800 rounded-full border-2 border-slate-300 dark:border-slate-700 overflow-hidden relative shadow-inner">
            <div className="absolute top-0 left-1/2 w-0.5 h-full bg-slate-400 dark:bg-slate-500 z-10"></div>
            <div className="absolute inset-0 bg-gradient-to-r from-pink-500 via-slate-200 to-blue-500 dark:from-pink-900 dark:via-slate-800 dark:to-blue-900 opacity-30"></div>
            <div 
                className="absolute top-0 bottom-0 transition-all duration-1000 ease-out z-20"
                style={{ 
                    right: `${100 - getZPercent(safeCoords.z)}%`, 
                    width: '6px',
                    backgroundColor: '#dc2626',
                    boxShadow: '0 0 10px rgba(220,38,38,0.8)',
                    borderRadius: '99px',
                    transform: 'translateX(50%)'
                }}
            ></div>
            {compareCoordinates && (
                <div 
                    className="absolute top-0 bottom-0 transition-all duration-1000 ease-out z-15"
                    style={{ 
                        right: `${100 - getZPercent(Number(compareCoordinates.z) || 0)}%`, 
                        width: '4px',
                        backgroundColor: '#64748b',
                        boxShadow: '0 0 6px rgba(100,116,139,0.8)',
                        borderRadius: '99px',
                        transform: 'translateX(50%)',
                        opacity: 0.8
                    }}
                ></div>
            )}
        </div>
        <div className="flex justify-between text-[10px] font-bold text-slate-500 uppercase tracking-tighter">
            <span>פרוגרסיבי / ליברלי</span>
            <span>מרכז</span>
            <span>שמרני / דתי</span>
        </div>
      </div>
    </div>
  );
};

