import { GoogleGenAI, Type } from "@google/genai";
import { Coordinates, AnalysisResult } from "../types";

/**
 * Advanced political analysis engine using Google Gemini API.
 * Analyzes X (Economic), Y (National Security), and Z (Conservatism)
 */
export const analyzeResults = async (coords: Coordinates): Promise<AnalysisResult> => {
  // Initialize Google GenAI with the API key from environment variables.
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const prompt = `
    Analyze a person's political identity based on their position on a 3-axis political compass in the Israeli context:
    - Economic Axis (X): ${coords.x.toFixed(2)} (Range: -10 Socialist/Left to +10 Capitalist/Right)
    - National Security Axis (Y): ${coords.y.toFixed(2)} (Range: -10 Dove/Left to +10 Hawk/Right)
    - Conservatism/Religious Axis (Z): ${coords.z.toFixed(2)} (Range: -10 Progressive/Secular to +10 Conservative/Religious)

    Based on these precise coordinates, determine their identity title and provide a deep analysis in Hebrew for each category.
  `;

  try {
    // Call generateContent with the model name and prompt directly.
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        systemInstruction: "You are a world-class political scientist specializing in Israeli politics. Provide an objective, nuanced, and insightful analysis of a person's political worldview in Hebrew. Be respectful and analytical.",
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            title: { 
              type: Type.STRING, 
              description: "A short identity title in Hebrew (e.g., 'ימין לאומי שמרני')" 
            },
            description: { 
              type: Type.STRING, 
              description: "A general overview of their worldview (1-2 sentences)" 
            },
            economicAnalysis: { 
              type: Type.STRING, 
              description: "Detailed analysis of economic and social views" 
            },
            nationalAnalysis: { 
              type: Type.STRING, 
              description: "Detailed analysis of national security and diplomatic views" 
            },
            religiousAnalysis: { 
              type: Type.STRING, 
              description: "Detailed analysis of religion and state / social conservatism views" 
            },
          },
          required: ["title", "description", "economicAnalysis", "nationalAnalysis", "religiousAnalysis"],
          propertyOrdering: ["title", "description", "economicAnalysis", "nationalAnalysis", "religiousAnalysis"]
        }
      }
    });

    // Directly access the .text property of GenerateContentResponse.
    const data = JSON.parse(response.text || "{}");

    return {
      title: data.title || "ניתוח לא ידוע",
      description: data.description || "",
      ideology: "", // Legacy field
      economicAnalysis: data.economicAnalysis || "",
      nationalAnalysis: data.nationalAnalysis || "",
      religiousAnalysis: data.religiousAnalysis || ""
    };
  } catch (error) {
    console.error("Gemini Analysis failed, falling back to deterministic engine:", error);
    return fallbackAnalysis(coords);
  }
};

/**
 * Deterministic fallback analysis if API fails or for offline mode.
 */
const fallbackAnalysis = (coords: Coordinates): AnalysisResult => {
  const { x, y, z } = coords;

  const isRight = x >= 0;
  const isHawk = y >= 0;
  const isConservative = z >= 0;

  let title = "";
  let description = "";

  if (isRight) {
    if (isHawk) {
      title = isConservative ? "ימין לאומי-שמרני" : "ימין לאומי-ליברלי";
      description = "אתה דוגל בשוק חופשי, ריבונות מלאה ביהודה ושומרון וגישה ביטחונית תקיפה.";
    } else {
      title = isConservative ? "מרכז-ימין שמרני" : "ליברטריאניזם / ימין ליברלי";
      description = "החופש הכלכלי והאישי עומדים בראש סדר העדיפויות שלך, לצד גישה מדינית פרגמטית.";
    }
  } else {
    if (isHawk) {
      title = isConservative ? "שמאל ביטחוני-שמרני" : "שמאל ביטחוני-ליברלי";
      description = "אתה תומך במדינת רווחה חזקה ובמעורבות ממשלתית, אך מחזיק בעמדות ניציות בנושאי ביטחון.";
    } else {
      title = isConservative ? "שמאל חברתי-מסורתי" : "שמאל ליברלי / סוציאל-דמוקרטיה";
      description = "השקפת עולמך מתמקדת בצמצום פערים חברתיים, פשרה מדינית וקידום ערכים אוניברסליים.";
    }
  }

  return {
    title,
    description,
    ideology: "",
    economicAnalysis: x >= 0 ? "כלכלה חופשית ויוזמה פרטית." : "מדינת רווחה וצמצום פערים.",
    nationalAnalysis: y >= 0 ? "גישה לאומית וביטחונית תקיפה." : "פרגמטיזם מדיני וחתירה להסדר.",
    religiousAnalysis: z >= 0 ? "שמירה על ערכי מסורת וזהות יהודית." : "ליברליות חילונית והפרדת דת ומדינה."
  };
};

