import { reportResult } from '../services/reportingService';
import { RefreshCw, Sparkles, Share2, Check, Download, Compass, Wallet, Shield, ScrollText, RotateCcw, Youtube } from 'lucide-react';
import html2canvas from 'html2canvas';

interface ResultViewProps {
  coordinates: Coordinates;
  compareCoordinates?: Coordinates | null;
  onRetake: () => void;
  initialAnalysis?: AnalysisResult | null;
  onAnalysisComplete?: (analysis: AnalysisResult) => void;
  isDarkMode?: boolean;
  isAccessible?: boolean;
  quizDuration?: number;
  answers?: Answer[];
  userName?: string;
  userEmail?: string;
  friendName?: string;
}

const ResultView: React.FC<ResultViewProps> = ({ 
  coordinates, 
  compareCoordinates,
  onRetake, 
  initialAnalysis = null, 
  onAnalysisComplete,
  isDarkMode = false,
  isAccessible = false,
  quizDuration = 0,
  answers = [],
  userName = "אני",
  userEmail = "",
  friendName
}) => {
  const [analysis, setAnalysis] = useState<AnalysisResult | null>(initialAnalysis);
  const [loading, setLoading] = useState(!initialAnalysis);
  const [copied, setCopied] = useState(false);
  const [downloading, setDownloading] = useState(false);

  const hasReportedRef = useRef(false);
  const downloadContainerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (initialAnalysis) {
      setAnalysis(initialAnalysis);
      setLoading(false);
      return;
    }

    let isMounted = true;
    const fetchAnalysis = async () => {
      setLoading(true);
      const result = await analyzeResults(coordinates);

      if (isMounted) {
        setAnalysis(result);
        setLoading(false);
        if (onAnalysisComplete) {
          onAnalysisComplete(result);
        }

        if (!hasReportedRef.current) {
            hasReportedRef.current = true;
            reportResult(coordinates, result, {
              duration: quizDuration,
              answers: answers,
              userName: userName || "Anonymous",
              userEmail: userEmail || "",
              comparedWith: friendName
            });
        }
      }
    };
    fetchAnalysis();
    return () => { isMounted = false; };
  }, [coordinates, initialAnalysis]);

  const handleShare = async () => {
    if (!analysis) return;
    const nameForShare = userName && userName !== "אני" ? userName : "מישהו";
    const params = new URLSearchParams();
    params.set('x', coordinates.x.toString());
    params.set('y', coordinates.y.toString());
    params.set('z', coordinates.z.toString());
    params.set('title', encodeURIComponent(analysis.title));
    params.set('desc', encodeURIComponent(analysis.description));
    params.set('name', encodeURIComponent(nameForShare));

    const shareUrl = `${window.location.origin}${window.location.pathname}?${params.toString()}`;
    const text = `התוצאה שלי במצפן הפוליטי: ${analysis.title}. בואו לגלות את שלכם:`;

    if (navigator.share) {
      try {
        await navigator.share({ title: 'המצפן הפוליטי', text: text, url: shareUrl });
      } catch (err) { console.log('Error sharing:', err); }
    } else {
      try {
        await navigator.clipboard.writeText(`${text}\n${shareUrl}`);
        setCopied(true);
        setTimeout(() => setCopied(false), 2000);
      } catch (err) { console.error('Failed to copy:', err); }
    }
  };

  const handleDownload = async () => {
    if (!downloadContainerRef.current || downloading) return;
    setDownloading(true);

    try {
      // Delay slightly to ensure component rendering
      await new Promise(r => setTimeout(r, 500));

      const canvas = await html2canvas(downloadContainerRef.current, {
        backgroundColor: '#ffffff',
        scale: 2, 
        useCORS: true,
        logging: false,
        width: 600,
        height: 750
      });

      const link = document.createElement('a');
      link.download = `political-compass-${userName || 'result'}.png`;
      link.href = canvas.toDataURL('image/png');
      link.click();
    } catch (err) {
      console.error('Download failed:', err);
    } finally {
      setDownloading(false);
    }
  };

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center py-24 space-y-6">
        <div className="relative">
          <RefreshCw className="w-16 h-16 text-yellow-500 animate-spin" />
        </div>
        <div className="text-center px-4">
          <h3 className="text-2xl font-black text-slate-900 dark:text-white mb-2">מחשב תוצאות...</h3>
          <p className="text-slate-500 dark:text-slate-400 font-medium">המערכת מעבדת את התשובות שלך</p>
        </div>
      </div>
    );
  }

  return (
    <div className="w-full max-w-5xl mx-auto px-4 pb-20 animate-fadeIn" dir="rtl">

      {/* Hidden Download Infographic Card (Fixed 600x750 Aspect) */}
      <div className="fixed -left-[4000px] top-0 pointer-events-none">
        <div 
          ref={downloadContainerRef}
          className="w-[600px] h-[750px] bg-white p-10 flex flex-col items-center justify-between border-[12px] border-slate-900"
          style={{ fontFamily: 'Rubik, sans-serif' }}
          dir="rtl"
        >
          {/* Header */}
          <div className="w-full flex items-center justify-between border-b-4 border-slate-900 pb-4">
            <div className="flex items-center gap-3">
              <div className="bg-yellow-400 p-2 rounded-lg border-2 border-slate-950 shadow-[4px_4px_0px_#000]">
                <Compass className="w-8 h-8 text-slate-950" />
              </div>
              <div className="text-right">
                <h1 className="text-2xl font-black text-slate-950 leading-none">המצפן הפוליטי</h1>
                <span className="text-xs font-bold text-slate-500 uppercase tracking-tighter">PROJECT DAAT • פרויקט דעת</span>
              </div>
            </div>
            <div className="bg-red-600 text-white p-2 rounded-lg border-2 border-slate-950 flex items-center gap-1">
              <Youtube className="w-4 h-4" fill="white" />
              <span className="text-[10px] font-black">SUBSCRIBE</span>
            </div>
          </div>

          {/* Title Area */}
          <div className="text-center mt-4 mb-2">
            <h2 className="text-lg font-bold text-slate-500 mb-1">הזהות של {userName && userName !== "אני" ? userName : 'מישהו'} היא:</h2>
            <div className="bg-yellow-400 border-4 border-slate-950 px-6 py-2 shadow-[6px_6px_0px_#000]">
              <h3 className="text-4xl font-black text-slate-950 uppercase">{analysis?.title}</h3>
            </div>
          </div>

          {/* Chart Area */}
          <div className="w-full flex justify-center scale-[0.85] -my-4">
            <CompassChart coordinates={coordinates} isPrinting={true} hideControls={true} />
