        </div>

        {/* Coordinates in chart corner */}
        {isPrinting && (
           <div className="absolute -bottom-6 -right-2 text-[12px] font-bold text-slate-600">
             ({safeCoords.x.toFixed(1)} , {safeCoords.y.toFixed(1)})
