import React from 'react';
import { Scale } from 'lucide-react';

interface ConservatismMeterProps {
  score: number;
  isPrinting?: boolean;
  isAccessible?: boolean;
}

const ConservatismMeter: React.FC<ConservatismMeterProps> = ({ score, isPrinting = false, isAccessible = false }) => {
  const safeScore = Math.max(-10, Math.min(10, score));
  // Convert -10..10 to 0..100
  // -10 (Progressive) -> 0% (Left)
  // +10 (Conservative) -> 100% (Right)
  const percentage = ((safeScore + 10) / 20) * 100;

  let label = "מאוזן";
  if (safeScore > 2) label = "נוטה לשמרנות";
  if (safeScore > 6) label = "שמרן";
  if (safeScore < -2) label = "נוטה לפרוגרסיביות";
  if (safeScore < -6) label = "פרוגרסיבי";

  // Styles based on printing mode or accessible mode
  let containerClass = "w-full mt-8 bg-white dark:bg-slate-800/50 p-6 rounded-2xl border border-slate-200 dark:border-slate-700/50";
  if (isPrinting) {
      containerClass = "w-[800px] mt-12 bg-white p-8 rounded-[40px] border-4 border-slate-200 shadow-sm mx-auto";
  } else if (isAccessible) {
      containerClass = "w-full mt-8 bg-white p-6 rounded-xl border-4 border-black";
  }

  let titleClass = "font-black text-slate-900 dark:text-white text-lg flex items-center gap-2";
  if (isPrinting) {
      titleClass = "font-black text-slate-900 text-3xl flex items-center gap-4";
  } else if (isAccessible) {
      titleClass = "font-black text-black text-xl flex items-center gap-2";
  }

  let labelBadgeClass = "text-sm font-bold text-slate-500 dark:text-slate-400 bg-slate-100 dark:bg-slate-800 px-2 py-1 rounded-md";
  if (isPrinting) {
      labelBadgeClass = "text-2xl font-bold text-slate-600 bg-slate-100 px-4 py-2 rounded-xl";
  } else if (isAccessible) {
      labelBadgeClass = "text-lg font-bold text-black bg-slate-200 border-2 border-black px-3 py-1 rounded-lg";
  }

  const trackHeight = isPrinting ? "h-6" : isAccessible ? "h-6" : "h-3";
  const trackContainerHeight = isPrinting ? "h-24 mb-4" : isAccessible ? "h-16 mb-2" : "h-14 mb-2";
  const tickClass = isPrinting 
    ? "w-1 h-10 bg-slate-400" 
    : isAccessible 
        ? "w-1 h-8 bg-black"
        : "w-0.5 h-5 bg-slate-400 dark:bg-slate-500";

  const markerSize = isPrinting ? "w-8 h-8 border-4" : isAccessible ? "w-6 h-6 border-4" : "w-4 h-4 border-2";

  let markerTextClass = "absolute -top-6 bg-slate-900 dark:bg-white text-white dark:text-slate-900 text-[10px] font-bold px-1.5 py-0.5 rounded shadow-sm";
  if (isPrinting) {
      markerTextClass = "absolute -top-12 bg-slate-900 text-white text-xl font-bold px-3 py-1 rounded-lg shadow-sm";
  } else if (isAccessible) {
      markerTextClass = "absolute -top-8 bg-black text-white text-base font-bold px-2 py-1 rounded border border-white";
  }

  let axisLabelsClass = "flex justify-between text-xs font-bold text-slate-400 dark:text-slate-500 px-1";
  if (isPrinting) {
      axisLabelsClass = "flex justify-between text-xl font-bold text-slate-500 px-2 mt-2";
  } else if (isAccessible) {
      axisLabelsClass = "flex justify-between text-base font-black text-black px-1";
  }

  const iconSize = isPrinting ? "w-10 h-10" : "w-5 h-5";

  return (
    <div className={containerClass}>
      <div className="flex items-center justify-between mb-6">
        <h3 className={titleClass}>
            <Scale className={`${iconSize} ${isAccessible ? 'text-black' : 'text-purple-500'}`} />
            מדד שמרנות-פרוגרסיביות
        </h3>
        <span className={labelBadgeClass}>
            {label}
        </span>
      </div>

      <div className={`relative ${trackContainerHeight}`}>
        {/* Track */}
        <div className={`absolute top-1/2 -translate-y-1/2 w-full ${trackHeight} ${isAccessible ? 'bg-white border-2 border-black' : 'bg-slate-200 dark:bg-slate-700'} rounded-full overflow-hidden`}>
             {/* Gradient: Left (Cyan/Prog) to Right (Purple/Cons) */}
             {!isAccessible ? (
                <div className="absolute inset-0 bg-gradient-to-r from-cyan-500 via-slate-300 dark:via-slate-600 to-purple-500 opacity-80"></div>
             ) : (
                <div className="absolute inset-0 bg-gradient-to-r from-blue-200 via-white to-purple-200"></div>
             )}
        </div>

        {/* Center Tick */}
        <div className={`absolute top-1/2 -translate-y-1/2 left-1/2 ${tickClass} -translate-x-1/2 z-0`}></div>

        {/* Marker */}
        <div 
            className="absolute top-0 bottom-0 w-1 z-10 transition-all duration-1000 ease-out flex flex-col items-center justify-center"
            style={{ left: `${percentage}%`, transform: 'translateX(-50%)' }}
        >
            <div className={`${markerSize} bg-slate-900 dark:bg-white rounded-full shadow-[0_0_10px_rgba(0,0,0,0.3)] ${isPrinting ? 'border-white' : isAccessible ? 'bg-black border-white' : 'border-white dark:border-slate-800'}`}></div>
            <div className={`${markerTextClass} opacity-100 whitespace-nowrap`}>
                {safeScore.toFixed(1)}
            </div>
        </div>
      </div>

      {/* Labels - RTL Flex: First is Right, Second is Left */}
      <div className={axisLabelsClass}>
         {/* Right Side (Positive/Conservative) */}
         <span className={isAccessible ? "text-black" : "text-purple-600 dark:text-purple-400"}>שמרן</span>
         {/* Left Side (Negative/Progressive) */}
         <span className={isAccessible ? "text-black" : "text-cyan-600 dark:text-cyan-400"}>פרוגרסיבי</span>
      </div>
    </div>
  );
};

