                ? 'flex items-center gap-2 px-8 py-4 bg-white text-black font-bold border-2 border-black hover:bg-slate-100'
                : 'flex items-center gap-2 px-8 py-4 bg-white dark:bg-slate-900 text-slate-500 dark:text-slate-400 font-bold rounded-2xl border border-slate-200 dark:border-slate-800 hover:text-yellow-600 dark:hover:text-yellow-400 transition-all'}`}
            >
