    if (savedUser) {
        setUserName(savedUser.name);
        setUserEmail(savedUser.email);
    }

    const params = new URLSearchParams(window.location.search);
    const xParam = params.get('x');
    const yParam = params.get('y');
    const zParam = params.get('z');

    if (xParam && yParam) {
      const x = parseFloat(xParam);
      const y = parseFloat(yParam);
      const z = zParam ? parseFloat(zParam) : 0;

      if (!isNaN(x) && !isNaN(y)) {
        const coords = { x, y, z };
        setFriendCoordinates(coords);
        setCoordinates(coords);

        const titleParam = params.get('title');
        const descParam = params.get('desc');
        const nameParam = params.get('name');

        if (nameParam) {
            setFriendName(decodeURIComponent(nameParam));
        }

        if (titleParam && descParam) {
          setCurrentAnalysis({
            title: decodeURIComponent(titleParam),
            description: decodeURIComponent(descParam),
            ideology: '',
            economicAnalysis: '',
            nationalAnalysis: '',
            religiousAnalysis: ''
          });
        }

        setAppState(AppState.RESULTS);
      }
    }
  }, []);

  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [isDarkMode]);

  const toggleTheme = () => setIsDarkMode(!isDarkMode);
  const toggleAccessibility = () => setIsAccessible(!isAccessible);

  const calculateResults = (answers: Answer[]) => {
    try {
      const durationSec = (Date.now() - startTime) / 1000;
      setQuizDuration(durationSec);
      setLastAnswers(answers);

      let econScore = 0;
      let nationalScore = 0;
      let socialScore = 0;

      const econQuestionsCount = QUESTIONS.filter(q => q.axis === Axis.ECONOMIC).length || 1;
      const nationalQuestionsCount = QUESTIONS.filter(q => q.axis === Axis.NATIONAL_SECURITY).length || 1;
      // Z-axis aggregates both Social/Cultural and Conservatism questions
      const socialQuestionsCount = QUESTIONS.filter(q => q.axis === Axis.SOCIAL_CULTURAL || q.axis === Axis.CONSERVATISM).length || 1;

      answers.forEach(ans => {
        const question = QUESTIONS.find(q => q.id === ans.questionId);
        if (!question) return;

        const score = Number(ans.score);
        const direction = Number(question.direction);

        if (isNaN(score) || isNaN(direction)) return;

        const impact = score * direction;

        if (question.axis === Axis.ECONOMIC) {
          econScore += impact;
        } else if (question.axis === Axis.NATIONAL_SECURITY) {
          nationalScore += impact;
        } else if (question.axis === Axis.SOCIAL_CULTURAL || question.axis === Axis.CONSERVATISM) {
          socialScore += impact;
        }
      });

      const normalizedX = (econScore / (2 * econQuestionsCount)) * 10;
      const normalizedY = (nationalScore / (2 * nationalQuestionsCount)) * 10;
      const normalizedZ = (socialScore / (2 * socialQuestionsCount)) * 10;

      const safeX = Math.max(-10, Math.min(10, normalizedX || 0));
      const safeY = Math.max(-10, Math.min(10, normalizedY || 0));
      const safeZ = Math.max(-10, Math.min(10, normalizedZ || 0));

      setCoordinates({ x: safeX, y: safeY, z: safeZ });
      setCurrentAnalysis(null);
      setAppState(AppState.RESULTS);

      // Trigger Channel Popup after results are calculated
      setTimeout(() => setShowChannelPopup(true), 2500);

      try {
        window.history.replaceState({}, document.title, window.location.pathname);
      } catch (historyError) {
        console.warn("Could not update history state:", historyError);
      }
    } catch (error) {
      console.error("Error calculating results:", error);
      setAppState(AppState.WELCOME);
    }
  };

  const handleAnalysisComplete = (analysis: AnalysisResult) => {
    saveResult({
      coordinates,
      analysis,
      timestamp: Date.now(),
      userName: userName,
      userEmail: userEmail
    });
    setHasHistory(true);
  };

  const handleLoadHistory = () => {
    const saved = getSavedResult();
    if (saved) {
      setCoordinates(saved.coordinates);
      setCurrentAnalysis(saved.analysis);
      setFriendCoordinates(null);
      setFriendName("");

      if (saved.userName) setUserName(saved.userName);
      if (saved.userEmail) setUserEmail(saved.userEmail || "");

      setAppState(AppState.RESULTS);
    }
  };

  const handleGoToRegistration = () => {
    setAppState(AppState.REGISTRATION);
  };

  const handleStartQuiz = () => {
    if (!userName.trim()) {
      setValidationError(true);
      return;
    }
    setStartTime(Date.now());
    setAppState(AppState.QUIZ);
  };

  const handleRetake = () => {
    try {
      window.history.pushState({}, document.title, window.location.pathname);
    } catch (historyError) {
      console.warn("Could not push history state:", historyError);
    }

    setAppState(AppState.WELCOME);
    setCoordinates({ x: 0, y: 0, z: 0 });
    setFriendCoordinates(null);
    setFriendName("");
    setCurrentAnalysis(null);
    setQuizDuration(0);
    setLastAnswers([]);
    setValidationError(false);
  };

  const isViewingFriendResult = appState === AppState.RESULTS && 
                                friendCoordinates !== null && 
                                coordinates.x === friendCoordinates.x && 
                                coordinates.y === friendCoordinates.y;

  return (
    <div 
      className={`min-h-screen flex flex-col font-sans transition-colors duration-300 ${isAccessible ? 'accessible-mode bg-white' : ''}`} 
      dir="rtl"
    >
      {showChannelPopup && <ChannelPopup onClose={() => setShowChannelPopup(false)} />}

      {/* Header */}
      <header className={`${isAccessible ? 'bg-white border-b-2 border-black' : 'bg-white/80 dark:bg-slate-900/80 border-b border-slate-200 dark:border-slate-800 glass transition-colors duration-300'} sticky top-0 z-50`}>
        <div className="max-w-6xl mx-auto px-4 h-16 flex items-center justify-between">
          <div 
            className="flex items-center gap-3 cursor-pointer group" 
            onClick={handleRetake}
            tabIndex={0}
            role="button"
            aria-label="חזור לדף הבית"
          >
            <div className={`${isAccessible ? 'bg-black text-white p-2 rounded' : 'bg-yellow-400 text-slate-950 p-1.5 rounded-lg shadow-[0_0_15px_rgba(250,204,21,0.3)] group-hover:scale-110 transition-transform'}`}>
                <Compass className="w-6 h-6" strokeWidth={2.5} />
            </div>
            <div>
                <h1 className={`text-xl font-black tracking-tight leading-none text-right ${isAccessible ? 'text-black' : 'text-slate-900 dark:text-slate-100'}`}>המצפן הפוליטי</h1>
                <span className={`text-xs font-bold tracking-wider block text-right ${isAccessible ? 'text-black' : 'text-yellow-500 dark:text-yellow-400'}`}>פרוייקט דעת</span>
            </div>
          </div>

          <div className="flex items-center gap-4">
             <button
               onClick={toggleAccessibility}
               aria-label={isAccessible ? "כבה מצב נגישות" : "הפעל מצב נגישות"}
               className={`p-2 rounded-full transition-colors ${
                 isAccessible 
                   ? 'bg-blue-800 text-white shadow-lg ring-4 ring-black' 
                   : 'bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-300 hover:bg-slate-200 dark:hover:bg-slate-700'
               }`}
             >
               <Accessibility className="w-5 h-5" />
             </button>

             <button 
              onClick={toggleTheme}
              aria-label={isDarkMode ? "עבור למצב יום" : "עבור למצב לילה"}
              className={`p-2 rounded-full transition-colors ${isAccessible ? 'bg-slate-200 text-black border border-black' : 'bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-300 hover:bg-slate-200 dark:hover:bg-slate-700'}`}
             >
                {isDarkMode ? <Sun className="w-5 h-5" /> : <Moon className="w-5 h-5" />}
             </button>

            <div className={`hidden md:flex items-center gap-2 text-xs font-medium px-3 py-1 rounded-full ${isAccessible ? 'bg-white border border-black text-black' : 'text-slate-500 dark:text-slate-400 bg-slate-100 dark:bg-slate-900/50 border border-slate-200 dark:border-slate-800'}`}>
                <span>פותח ע"י חגי</span>
            </div>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 flex flex-col items-center justify-center py-8 relative overflow-hidden">
        {!isAccessible && (
          <>
            <div className="absolute top-10 left-10 w-96 h-96 bg-yellow-400/20 dark:bg-yellow-500/10 rounded-full filter blur-3xl opacity-30 dark:opacity-20 animate-blob"></div>
            <div className="absolute bottom-10 right-10 w-96 h-96 bg-blue-400/20 dark:bg-slate-700/20 rounded-full filter blur-3xl opacity-30 dark:opacity-20 animate-blob animation-delay-2000"></div>
          </>
        )}

        <div className="z-10 w-full">
            {appState === AppState.WELCOME && (
            <div className="max-w-2xl mx-auto px-4 animate-fadeIn">
                <div className={`${isAccessible ? 'bg-white border-4 border-black p-8 rounded-xl shadow-none' : 'bg-white/80 dark:bg-slate-900/60 backdrop-blur-xl p-8 md:p-12 rounded-[2.5rem] shadow-2xl border border-slate-200 dark:border-slate-800 relative overflow-hidden ring-1 ring-black/5 dark:ring-white/5 transition-colors duration-300'}`}>
                {!isAccessible && <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-yellow-500 via-yellow-400 to-yellow-500"></div>}

                <div className={`mb-6 inline-flex items-center justify-center p-4 rounded-2xl ${isAccessible ? 'bg-white border-2 border-black' : 'bg-slate-50 dark:bg-slate-800/50 shadow-inner border border-slate-100 dark:border-slate-700'}`}>
                    <BrainCircuit className={`w-12 h-12 ${isAccessible ? 'text-black' : 'text-yellow-500 dark:text-yellow-400'}`} />
                </div>

                <div className="mb-6">
                    <span className={`inline-block px-4 py-1.5 text-sm font-black rounded-full shadow-sm ${isAccessible ? 'bg-white border-2 border-black text-black' : 'bg-yellow-100 dark:bg-yellow-900/30 text-yellow-800 dark:text-yellow-200 border border-yellow-200 dark:border-yellow-700'}`}>
                        🇮🇱 המצפן הפוליטי היחיד בישראל
                    </span>
                </div>

                <h2 className={`text-4xl md:text-5xl font-black mb-6 tracking-tight ${isAccessible ? 'text-black' : 'text-slate-900 dark:text-white'}`}>
                    גלה את <span className={isAccessible ? "text-black underline decoration-4" : "text-transparent bg-clip-text bg-gradient-to-r from-yellow-500 to-yellow-600 dark:from-yellow-200 dark:to-yellow-500"}>הזהות הפוליטית</span> שלך
                </h2>

                <p className={`text-lg md:text-xl mb-10 leading-relaxed max-w-lg mx-auto font-medium ${isAccessible ? 'text-black font-bold' : 'text-slate-600 dark:text-slate-400'}`}>
                    הצטרף לאלפי ישראלים המשתתפים במחקר של פרוייקט דעת.
                    <br/>
                    האלגוריתם ינתח את עמדותיך ב-49 סוגיות ליבה וימקם אותך במדויק על המפה הפוליטית.
                </p>

                <div className="space-y-4 max-w-md mx-auto">
                    <button 
                    onClick={handleGoToRegistration}
                    className={`w-full px-8 py-5 text-xl font-black rounded-2xl flex items-center justify-center gap-3 ${isAccessible ? 'bg-black text-white border-4 border-black hover:bg-slate-800' : 'bg-yellow-400 text-slate-950 hover:bg-yellow-300 transition-all hover:-translate-y-1 hover:shadow-[0_0_20px_rgba(250,204,21,0.4)] active:scale-95 shadow-lg'}`}
                    >
                    <span>התחל במבחן</span>
                    <Compass className="w-6 h-6" />
                    </button>

                    {hasHistory && (
                    <button 
                        onClick={handleLoadHistory}
                        className={`w-full px-8 py-4 text-lg font-bold rounded-2xl flex items-center justify-center gap-2 ${isAccessible ? 'bg-white text-black border-4 border-black hover:bg-slate-100' : 'bg-white dark:bg-slate-800/50 text-slate-700 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-slate-800 hover:text-yellow-600 dark:hover:text-yellow-400 transition-all shadow-sm'}`}
                    >
                        <History className="w-5 h-5" />
                        צפה בתוצאה אחרונה
                    </button>
                    )}
                </div>
                </div>
            </div>
            )}

            {appState === AppState.REGISTRATION && (
            <div className="max-w-md mx-auto px-4 animate-fadeIn">
                <div className={`${isAccessible ? 'bg-white border-4 border-black p-8 rounded-xl' : 'bg-white/80 dark:bg-slate-900/60 backdrop-blur-xl p-8 rounded-[2rem] shadow-2xl border border-slate-200 dark:border-slate-800'}`}>
                    <h2 className={`text-2xl font-black mb-6 text-center ${isAccessible ? 'text-black' : 'text-slate-900 dark:text-white'}`}>קצת פרטים ומתחילים</h2>

                    <div className="space-y-5">
                        <div>
                            <label htmlFor="userName" className={`block text-sm font-bold mb-1.5 mr-1 ${isAccessible ? 'text-black text-base' : 'text-slate-700 dark:text-slate-300'}`}>שם (חובה)</label>
                            <div className="relative">
                                <User className={`absolute right-3 top-3 w-5 h-5 ${isAccessible ? 'text-black' : 'text-slate-400'}`} />
                                <input 
                                    id="userName"
                                    type="text"
                                    value={userName}
                                    onChange={(e) => {
                                        setUserName(e.target.value);
                                        if(e.target.value) setValidationError(false);
                                    }}
                                    className={`w-full pr-10 pl-4 py-3 rounded-xl border outline-none font-medium ${isAccessible ? 'bg-white border-2 border-black text-black focus:ring-4 focus:ring-black' : `${validationError ? 'border-red-400 focus:ring-red-200' : 'border-slate-200 dark:border-slate-700 focus:ring-yellow-400/50'} bg-white dark:bg-slate-800 text-slate-900 dark:text-white transition-all focus:ring-2`}`}
                                    placeholder="ישראל ישראלי"
                                />
                            </div>
                            {validationError && <p className="text-red-600 font-bold text-xs mt-1 mr-1">אנא מלא את השם כדי להמשיך</p>}
                        </div>

                        <div>
                            <label htmlFor="userEmail" className={`block text-sm font-bold mb-1.5 mr-1 ${isAccessible ? 'text-black text-base' : 'text-slate-700 dark:text-slate-300'}`}>דואר אלקטרוני (רשות)</label>
                            <div className="relative">
                                <Mail className={`absolute right-3 top-3 w-5 h-5 ${isAccessible ? 'text-black' : 'text-slate-400'}`} />
                                <input 
                                    id="userEmail"
                                    type="email"
                                    value={userEmail}
                                    onChange={(e) => setUserEmail(e.target.value)}
                                    className={`w-full pr-10 pl-4 py-3 rounded-xl border outline-none font-medium ${isAccessible ? 'bg-white border-2 border-black text-black focus:ring-4 focus:ring-black' : 'border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white focus:ring-2 focus:ring-yellow-400/50 transition-all'}`}
                                    placeholder="your@email.com"
                                />
                            </div>
                        </div>

                        <button 
                            onClick={handleStartQuiz}
                            className={`w-full mt-4 px-8 py-4 text-lg font-black rounded-xl flex items-center justify-center gap-2 ${isAccessible ? 'bg-black text-white border-4 border-black hover:bg-slate-800' : 'bg-yellow-400 text-slate-950 hover:bg-yellow-300 transition-all hover:-translate-y-1 shadow-lg active:scale-95'}`}
                        >
                            <span>התחל מבחן</span>
                            <ArrowLeft className="w-5 h-5" />
                        </button>
                    </div>
                </div>
            </div>
            )}

            {appState === AppState.QUIZ && (
            <div className="animate-fadeIn">
                <Quiz onComplete={calculateResults} isAccessible={isAccessible} />
            </div>
            )}

            {appState === AppState.RESULTS && (
            <ResultView 
                coordinates={coordinates} 
                compareCoordinates={friendCoordinates}
                onRetake={handleRetake} 
                initialAnalysis={currentAnalysis}
                onAnalysisComplete={handleAnalysisComplete}
                isDarkMode={isDarkMode}
                isAccessible={isAccessible}
                quizDuration={quizDuration}
                answers={lastAnswers}
                userName={userName}
                userEmail={userEmail}
                friendName={friendName}
            />
            )}
        </div>
      </main>
    </div>
  );
};

export default App;

import React from 'react';
import { ScatterChart, Scatter, XAxis, YAxis, CartesianGrid, ResponsiveContainer, ReferenceLine, Cell, LabelList, ReferenceArea } from 'recharts';
import { Coordinates } from '../types';

interface CompassChartProps {
  coordinates: Coordinates;
  compareCoordinates?: Coordinates | null;
  userName?: string;
  friendName?: string;
  isDarkMode?: boolean;
  isAccessible?: boolean;
  hideControls?: boolean;
  isPrinting?: boolean; 
}

const CompassChart: React.FC<CompassChartProps> = ({ 
  coordinates, 
  compareCoordinates, 
  userName = "אני",
  friendName = "חבר",
  isDarkMode = false, 
  isAccessible = false, 
  hideControls = false,
  isPrinting = false
}) => {
  const safeCoords = {
    x: Number.isNaN(Number(coordinates.x)) ? 0 : Number(coordinates.x),
    y: Number.isNaN(Number(coordinates.y)) ? 0 : Number(coordinates.y),
    z: Number.isNaN(Number(coordinates.z)) ? 0 : Number(coordinates.z)
  };

  const userData = [{ x: safeCoords.x, y: safeCoords.y, name: userName || "אני" }];

  const compareData = compareCoordinates ? [{ 
    x: Number.isNaN(Number(compareCoordinates.x)) ? 0 : Number(compareCoordinates.x), 
    y: Number.isNaN(Number(compareCoordinates.y)) ? 0 : Number(compareCoordinates.y), 
    name: friendName || "חבר" 
  }] : [];

  // Colors matched to the user's mockup image
  const colors = isPrinting ? {
    authLeft: "#ffbaba", // Pink
    authRight: "#badaff", // Blue
    libLeft: "#baffba", // Green
    libRight: "#fff2ba", // Yellow
    grid: "#e2e8f0",
    axis: "#475569"
  } : isAccessible ? {
    // High contrast accessible colors (Pastel but distinctive with strong borders)
    authLeft: "#ffcccc",    // Reddish
    authRight: "#ccccff",   // Bluish
    libLeft: "#ccffcc",     // Greenish
    libRight: "#ffffcc",    // Yellowish
    grid: "#000000",        // Black grid
    axis: "#000000"         // Black axis
  } : {
    authLeft: "#ff4d4d", authRight: "#4d94ff", libLeft: "#44cc44", libRight: "#ffcc00",
    grid: (isDarkMode && !isPrinting) ? "#334155" : "#cbd5e1",
    axis: (isDarkMode && !isPrinting) ? "#f8fafc" : "#0f172a"
  };

  const opacity = (isAccessible || isPrinting) ? 1 : 0.7;
  const ticks = [-10, -8, -6, -4, -2, 0, 2, 4, 6, 8, 10];

  const ChartContent = (
    <ScatterChart 
      margin={{ top: 10, right: 10, bottom: 10, left: 10 }}
      width={isPrinting ? 500 : undefined}
      height={isPrinting ? 500 : undefined}
    >
      <XAxis type="number" dataKey="x" domain={[-10, 10]} ticks={ticks} hide />
      <YAxis type="number" dataKey="y" domain={[-10, 10]} ticks={ticks} hide />

      <ReferenceArea x1={-10} x2={0} y1={0} y2={10} fill={colors.authLeft} fillOpacity={opacity} />
      <ReferenceArea x1={0} x2={10} y1={0} y2={10} fill={colors.authRight} fillOpacity={opacity} />
      <ReferenceArea x1={-10} x2={0} y1={-10} y2={0} fill={colors.libLeft} fillOpacity={opacity} />
      <ReferenceArea x1={0} x2={10} y1={-10} y2={0} fill={colors.libRight} fillOpacity={opacity} />

      <CartesianGrid stroke={colors.grid} strokeDasharray={isAccessible ? "0" : "0"} strokeOpacity={isPrinting || isAccessible ? 1 : 0.3} strokeWidth={isAccessible ? 2 : 1} />
      <ReferenceLine x={0} stroke={colors.axis} strokeWidth={isAccessible ? 4 : 2} />
      <ReferenceLine y={0} stroke={colors.axis} strokeWidth={isAccessible ? 4 : 2} />

      {compareData.length > 0 && (
        <Scatter name={friendName} data={compareData} isAnimationActive={!isAccessible}>
          <Cell fill={isAccessible ? "#555" : "#475569"} stroke="white" strokeWidth={2} r={isPrinting ? 8 : 8} />
          <LabelList dataKey="name" position="top" offset={10} style={{ fill: '#0f172a', fontWeight: '800', fontSize: isPrinting ? '12px' : '11px', paintOrder: 'stroke', stroke: '#ffffff', strokeWidth: '3px' }} />
        </Scatter>
      )}

      <Scatter name={userName} data={userData} isAnimationActive={!isAccessible}>
        <Cell fill={isAccessible ? "#000" : "#dc2626"} stroke={isAccessible ? "#fff" : "#ffffff"} strokeWidth={isPrinting || isAccessible ? 2 : 3} r={isPrinting ? 6 : isAccessible ? 10 : 12} />
        {!isPrinting && <LabelList dataKey="name" position="top" offset={12} style={{ fill: isAccessible ? '#000' : '#0f172a', fontWeight: '900', fontSize: '13px', paintOrder: 'stroke', stroke: '#ffffff', strokeWidth: '4px' }} />}
      </Scatter>
    </ScatterChart>
  );

  // If printing, we use a dedicated grid layout to ensure labels are captured by html2canvas
  if (isPrinting) {
      return (
          <div className="flex flex-col items-center justify-center p-4 bg-transparent w-[700px]">
              {/* Top Label */}
              <div className="mb-2 text-center">
                  <span className="text-2xl font-black text-slate-500 uppercase tracking-tight block">
                    סמכותני (Authoritarian)
                  </span>
              </div>

              <div className="flex items-center justify-center gap-2">
                  {/* Left Label (Rotated) */}
                  <div className="h-[500px] w-12 flex items-center justify-center">
                      <span 
                        className="text-2xl font-black text-slate-500 uppercase tracking-tight whitespace-nowrap transform -rotate-90"
                      >
                         שמאל כלכלי (Economic Left)
                      </span>
                  </div>

                  {/* Chart */}
                  <div className="w-[500px] h-[500px] border-[2px] border-[#475569] bg-white overflow-hidden relative">
                      {ChartContent}
                      <div className="absolute -bottom-6 -right-2 text-[12px] font-bold text-slate-600">
                        ({safeCoords.x.toFixed(1)} , {safeCoords.y.toFixed(1)})
                      </div>
                  </div>

                  {/* Right Label (Rotated) */}
                  <div className="h-[500px] w-12 flex items-center justify-center">
                      <span 
                        className="text-2xl font-black text-slate-500 uppercase tracking-tight whitespace-nowrap transform rotate-90"
                      >
                         ימין כלכלי (Economic Right)
                      </span>
                  </div>
              </div>

               {/* Bottom Label */}
               <div className="mt-2 text-center">
                  <span className="text-2xl font-black text-slate-500 uppercase tracking-tight block">
                    ליברלי (Libertarian)
                  </span>
              </div>
          </div>
      );
  }

  // Standard Responsive Layout for Web View
  return (
    <div className="w-full flex flex-col items-center gap-6">
      {!hideControls && (
        <div className="w-full flex justify-center">
          <div className={`flex items-center gap-3 text-sm font-black px-6 py-3 rounded-2xl border-2 ${isAccessible ? 'bg-white border-black text-black' : 'bg-white/80 dark:bg-slate-800/80 border-slate-200 dark:border-slate-700 shadow-xl backdrop-blur-md text-slate-900 dark:text-white'}`}>
            <div className={`w-4 h-4 rounded-full ${isAccessible ? 'bg-black border border-white' : 'bg-red-600 ring-2 ring-white shadow-[0_0_10px_rgba(220,38,38,0.5)]'}`}></div>
            <span>המיקום הפוליטי שלך</span>
          </div>
