import AccessibilityMenu from './components/AccessibilityMenu';
import { Answer, Coordinates, AnalysisResult, Axis } from './types';
import { QUESTIONS } from './constants';
import { Compass, History, BrainCircuit, HeartHandshake, Moon, Sun, User, Mail, ArrowLeft, Accessibility, Users } from 'lucide-react';
import { getSavedResult, saveResult, hasSavedResult, getSavedUserDetails } from './utils/storage';

enum AppState {
  WELCOME,
  REGISTRATION,
  QUIZ,
  RESULTS
}

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.WELCOME);
  const [coordinates, setCoordinates] = useState<Coordinates>({ x: 0, y: 0, z: 0 });
  const [friendCoordinates, setFriendCoordinates] = useState<Coordinates | null>(null);
  const [friendName, setFriendName] = useState<string>("");

  const [currentAnalysis, setCurrentAnalysis] = useState<AnalysisResult | null>(null);
  const [hasHistory, setHasHistory] = useState(false);
  const [isDarkMode, setIsDarkMode] = useState(true);
  const [isAccessible, setIsAccessible] = useState(false);
  const [showChannelPopup, setShowChannelPopup] = useState(false);

  // User Data State
  const [userName, setUserName] = useState("");
  const [userEmail, setUserEmail] = useState("");
  const [validationError, setValidationError] = useState(false);

  // Analytics State
  const [startTime, setStartTime] = useState<number>(0);
  const [quizDuration, setQuizDuration] = useState<number>(0);
  const [lastAnswers, setLastAnswers] = useState<Answer[]>([]);

  useEffect(() => {
    setHasHistory(hasSavedResult());

    const savedUser = getSavedUserDetails();
    if (savedUser) {
        setUserName(savedUser.name);
        setUserEmail(savedUser.email);
    }

    const params = new URLSearchParams(window.location.search);
    const xParam = params.get('x');
    const yParam = params.get('y');
    const zParam = params.get('z');

    if (xParam && yParam) {
      const x = parseFloat(xParam);
      const y = parseFloat(yParam);
      const z = zParam ? parseFloat(zParam) : 0;

      if (!isNaN(x) && !isNaN(y)) {
        const coords = { x, y, z };
        setFriendCoordinates(coords);
        setCoordinates(coords);

        const titleParam = params.get('title');
        const descParam = params.get('desc');
        const nameParam = params.get('name');

        if (nameParam) {
            setFriendName(decodeURIComponent(nameParam));
        }

        if (titleParam && descParam) {
          setCurrentAnalysis({
            title: decodeURIComponent(titleParam),
            description: decodeURIComponent(descParam),
            ideology: '',
            economicAnalysis: '',
            nationalAnalysis: '',
            religiousAnalysis: ''
          });
        }

        setAppState(AppState.RESULTS);
      }
    }
  }, []);

  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [isDarkMode]);

  const toggleTheme = () => setIsDarkMode(!isDarkMode);
  const toggleAccessibility = () => setIsAccessible(!isAccessible);

  const calculateResults = (answers: Answer[]) => {
    try {
      const durationSec = (Date.now() - startTime) / 1000;
      setQuizDuration(durationSec);
      setLastAnswers(answers);

      let econScore = 0;
      let nationalScore = 0;
      let socialScore = 0;

      const econQuestionsCount = QUESTIONS.filter(q => q.axis === Axis.ECONOMIC).length || 1;
      const nationalQuestionsCount = QUESTIONS.filter(q => q.axis === Axis.NATIONAL_SECURITY).length || 1;
      // Z-axis aggregates both Social/Cultural and Conservatism questions
      const socialQuestionsCount = QUESTIONS.filter(q => q.axis === Axis.SOCIAL_CULTURAL || q.axis === Axis.CONSERVATISM).length || 1;

      answers.forEach(ans => {
        const question = QUESTIONS.find(q => q.id === ans.questionId);
        if (!question) return;

        const score = Number(ans.score);
        const direction = Number(question.direction);

        if (isNaN(score) || isNaN(direction)) return;

        const impact = score * direction;

        if (question.axis === Axis.ECONOMIC) {
          econScore += impact;
        } else if (question.axis === Axis.NATIONAL_SECURITY) {
          nationalScore += impact;
        } else if (question.axis === Axis.SOCIAL_CULTURAL || question.axis === Axis.CONSERVATISM) {
          socialScore += impact;
        }
      });

      const normalizedX = (econScore / (2 * econQuestionsCount)) * 10;
      const normalizedY = (nationalScore / (2 * nationalQuestionsCount)) * 10;
      const normalizedZ = (socialScore / (2 * socialQuestionsCount)) * 10;

      const safeX = Math.max(-10, Math.min(10, normalizedX || 0));
      const safeY = Math.max(-10, Math.min(10, normalizedY || 0));
      const safeZ = Math.max(-10, Math.min(10, normalizedZ || 0));

      setCoordinates({ x: safeX, y: safeY, z: safeZ });
      setCurrentAnalysis(null);
      setAppState(AppState.RESULTS);

      // Trigger Channel Popup after results are calculated
      setTimeout(() => setShowChannelPopup(true), 2500);

      try {
        window.history.replaceState({}, document.title, window.location.pathname);
      } catch (historyError) {
        console.warn("Could not update history state:", historyError);
      }
    } catch (error) {
      console.error("Error calculating results:", error);
      setAppState(AppState.WELCOME);
    }
  };

  const handleAnalysisComplete = (analysis: AnalysisResult) => {
    saveResult({
      coordinates,
      analysis,
      timestamp: Date.now(),
      userName: userName,
      userEmail: userEmail
    });
    setHasHistory(true);
  };

  const handleLoadHistory = () => {
    const saved = getSavedResult();
    if (saved) {
      setCoordinates(saved.coordinates);
      setCurrentAnalysis(saved.analysis);
      setFriendCoordinates(null);
      setFriendName("");

      if (saved.userName) setUserName(saved.userName);
      if (saved.userEmail) setUserEmail(saved.userEmail || "");

      setAppState(AppState.RESULTS);
    }
  };

  const handleGoToRegistration = () => {
    setAppState(AppState.REGISTRATION);
  };

  const handleStartQuiz = () => {
    if (!userName.trim()) {
      setValidationError(true);
      return;
    }
    setStartTime(Date.now());
    setAppState(AppState.QUIZ);
  };

  const handleRetake = () => {
    try {
      window.history.pushState({}, document.title, window.location.pathname);
    } catch (historyError) {
      console.warn("Could not push history state:", historyError);
    }

    setAppState(AppState.WELCOME);
    setCoordinates({ x: 0, y: 0, z: 0 });
    setFriendCoordinates(null);
    setFriendName("");
    setCurrentAnalysis(null);
    setQuizDuration(0);
    setLastAnswers([]);
    setValidationError(false);
  };

  const isViewingFriendResult = appState === AppState.RESULTS && 
                                friendCoordinates !== null && 
                                coordinates.x === friendCoordinates.x && 
                                coordinates.y === friendCoordinates.y;

  return (
    <div 
      className={`min-h-screen flex flex-col font-sans transition-colors duration-300 ${isAccessible ? 'accessible-mode' : ''}`} 
      dir="rtl"
    >
      {showChannelPopup && <ChannelPopup onClose={() => setShowChannelPopup(false)} />}

      {/* Floating Accessibility Widget */}
      <AccessibilityMenu 
        isHighContrast={isAccessible} 
        toggleHighContrast={toggleAccessibility}
        isDarkMode={isDarkMode}
        toggleTheme={toggleTheme}
      />

      {/* Header */}
      <header className="bg-white/80 dark:bg-slate-900/80 border-b border-slate-200 dark:border-slate-800 sticky top-0 z-50 glass transition-colors duration-300">
        <div className="max-w-6xl mx-auto px-4 h-16 flex items-center justify-between">
          <div 
            className="flex items-center gap-3 cursor-pointer group" 
            onClick={handleRetake}
            tabIndex={0}
          >
            <div className="bg-yellow-400 text-slate-950 p-1.5 rounded-lg shadow-[0_0_15px_rgba(250,204,21,0.3)] group-hover:scale-110 transition-transform">
                <Compass className="w-6 h-6" strokeWidth={2.5} />
            </div>
            <div>
                <h1 className="text-xl font-black tracking-tight leading-none text-slate-900 dark:text-slate-100 text-right">המצפן הפוליטי</h1>
                <span className="text-xs text-yellow-500 dark:text-yellow-400 font-bold tracking-wider block text-right">פרוייקט דעת</span>
            </div>
          </div>

          <div className="flex items-center gap-4">
             {/* Accessibility button removed from here, now it's a floating widget */}
             {/* Theme toggle removed from here, moved to widget */}

            <div className="hidden md:flex items-center gap-2 text-xs font-medium text-slate-500 dark:text-slate-400 bg-slate-100 dark:bg-slate-900/50 px-3 py-1 rounded-full border border-slate-200 dark:border-slate-800">
                <span>פותח ע"י חגי</span>
            </div>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 flex flex-col items-center justify-center py-8 relative overflow-hidden">
        {!isAccessible && (
          <>
            <div className="absolute top-10 left-10 w-96 h-96 bg-yellow-400/20 dark:bg-yellow-500/10 rounded-full filter blur-3xl opacity-30 dark:opacity-20 animate-blob"></div>
            <div className="absolute bottom-10 right-10 w-96 h-96 bg-blue-400/20 dark:bg-slate-700/20 rounded-full filter blur-3xl opacity-30 dark:opacity-20 animate-blob animation-delay-2000"></div>
          </>
        )}

        <div className="z-10 w-full">
            {appState === AppState.WELCOME && (
            <div className="max-w-2xl mx-auto px-4 text-center animate-fadeIn">
                <div className="bg-white/80 dark:bg-slate-900/60 backdrop-blur-xl p-8 md:p-12 rounded-[2.5rem] shadow-2xl border border-slate-200 dark:border-slate-800 relative overflow-hidden ring-1 ring-black/5 dark:ring-white/5 transition-colors duration-300">
                <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-yellow-500 via-yellow-400 to-yellow-500"></div>

                <div className="mb-6 inline-flex items-center justify-center p-4 bg-slate-50 dark:bg-slate-800/50 rounded-2xl shadow-inner border border-slate-100 dark:border-slate-700">
                    <BrainCircuit className="w-12 h-12 text-yellow-500 dark:text-yellow-400" />
                </div>

                <div className="mb-6">
                    <span className="inline-block px-4 py-1.5 bg-yellow-100 dark:bg-yellow-900/30 text-yellow-800 dark:text-yellow-200 text-sm font-black rounded-full border border-yellow-200 dark:border-yellow-700 shadow-sm">
                        🇮🇱 המצפן הפוליטי היחיד בישראל
                    </span>
                </div>

                <h2 className="text-4xl md:text-5xl font-black text-slate-900 dark:text-white mb-6 tracking-tight">
                    גלה את <span className={isAccessible ? "text-yellow-700 dark:text-yellow-300 underline" : "text-transparent bg-clip-text bg-gradient-to-r from-yellow-500 to-yellow-600 dark:from-yellow-200 dark:to-yellow-500"}>הזהות הפוליטית</span> שלך
                </h2>

                <p className="text-lg md:text-xl text-slate-600 dark:text-slate-400 mb-10 leading-relaxed max-w-lg mx-auto font-medium">
                    הצטרף לאלפי ישראלים המשתתפים במחקר של פרוייקט דעת.
                    <br/>
                    האלגוריתם ינתח את עמדותיך ב-49 סוגיות ליבה וימקם אותך במדויק על המפה הפוליטית.
                </p>

                <div className="space-y-4 max-w-md mx-auto">
                    <button 
                    onClick={handleGoToRegistration}
                    className="w-full px-8 py-5 bg-yellow-400 text-slate-950 text-xl font-black rounded-2xl hover:bg-yellow-300 transition-all hover:-translate-y-1 hover:shadow-[0_0_20px_rgba(250,204,21,0.4)] active:scale-95 flex items-center justify-center gap-3 shadow-lg"
                    >
                    <span>התחל במבחן</span>
                    <Compass className="w-6 h-6" />
                    </button>

                    {hasHistory && (
                    <button 
                        onClick={handleLoadHistory}
                        className="w-full px-8 py-4 bg-white dark:bg-slate-800/50 text-slate-700 dark:text-slate-300 text-lg font-bold rounded-2xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-slate-800 hover:text-yellow-600 dark:hover:text-yellow-400 transition-all flex items-center justify-center gap-2 shadow-sm"
                    >
                        <History className="w-5 h-5" />
                        צפה בתוצאה אחרונה
                    </button>
                    )}
                </div>
                </div>
            </div>
            )}

            {appState === AppState.REGISTRATION && (
            <div className="max-w-md mx-auto px-4 animate-fadeIn">
                <div className="bg-white/80 dark:bg-slate-900/60 backdrop-blur-xl p-8 rounded-[2rem] shadow-2xl border border-slate-200 dark:border-slate-800">
                    <h2 className="text-2xl font-black text-slate-900 dark:text-white mb-6 text-center">קצת פרטים ומתחילים</h2>

                    <div className="space-y-5">
                        <div>
                            <label htmlFor="userName" className="block text-sm font-bold text-slate-700 dark:text-slate-300 mb-1.5 mr-1">שם (חובה)</label>
                            <div className="relative">
                                <User className="absolute right-3 top-3 w-5 h-5 text-slate-400" />
                                <input 
                                    id="userName"
                                    type="text"
                                    value={userName}
                                    onChange={(e) => {
                                        setUserName(e.target.value);
                                        if(e.target.value) setValidationError(false);
                                    }}
                                    className={`w-full pr-10 pl-4 py-3 rounded-xl border ${validationError ? 'border-red-400 focus:ring-red-200' : 'border-slate-200 dark:border-slate-700 focus:ring-yellow-400/50'} bg-white dark:bg-slate-800 text-slate-900 dark:text-white outline-none focus:ring-2 transition-all font-medium`}
                                    placeholder="ישראל ישראלי"
                                />
                            </div>
                            {validationError && <p className="text-red-500 text-xs mt-1 mr-1">אנא מלא את השם כדי להמשיך</p>}
                        </div>

                        <div>
                            <label htmlFor="userEmail" className="block text-sm font-bold text-slate-700 dark:text-slate-300 mb-1.5 mr-1">דואר אלקטרוני (רשות)</label>
                            <div className="relative">
                                <Mail className="absolute right-3 top-3 w-5 h-5 text-slate-400" />
                                <input 
                                    id="userEmail"
                                    type="email"
                                    value={userEmail}
                                    onChange={(e) => setUserEmail(e.target.value)}
                                    className="w-full pr-10 pl-4 py-3 rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white outline-none focus:ring-2 focus:ring-yellow-400/50 transition-all font-medium"
                                    placeholder="your@email.com"
                                />
                            </div>
                        </div>

                        <button 
                            onClick={handleStartQuiz}
                            className="w-full mt-4 px-8 py-4 bg-yellow-400 text-slate-950 text-lg font-black rounded-xl hover:bg-yellow-300 transition-all hover:-translate-y-1 shadow-lg active:scale-95 flex items-center justify-center gap-2"
                        >
                            <span>התחל מבחן</span>
                            <ArrowLeft className="w-5 h-5" />
                        </button>
                    </div>
                </div>
            </div>
            )}

            {appState === AppState.QUIZ && (
            <div className="animate-fadeIn">
                <Quiz onComplete={calculateResults} isAccessible={isAccessible} />
            </div>
            )}

            {appState === AppState.RESULTS && (
            <ResultView 
                coordinates={coordinates} 
                compareCoordinates={friendCoordinates}
                onRetake={handleRetake} 
                initialAnalysis={currentAnalysis}
                onAnalysisComplete={handleAnalysisComplete}
                isDarkMode={isDarkMode}
                isAccessible={isAccessible}
                quizDuration={quizDuration}
                answers={lastAnswers}
                userName={userName}
                userEmail={userEmail}
                friendName={friendName}
            />
            )}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Question, Answer } from '../types';
import { QUESTIONS } from '../constants';
import { ArrowLeft, ArrowRight, Check, ChevronRight, X, Minus } from 'lucide-react';

interface QuizProps {
  onComplete: (answers: Answer[]) => void;
  // Fix: Add isAccessible optional prop to interface
  isAccessible?: boolean;
}

const Quiz: React.FC<QuizProps> = ({ onComplete, isAccessible = false }) => {
  const [questions, setQuestions] = useState<Question[]>([]);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [answers, setAnswers] = useState<Answer[]>([]);
  const [animating, setAnimating] = useState(false);
  const [direction, setDirection] = useState<'forward' | 'backward'>('forward');

  useEffect(() => {
    // Fisher-Yates shuffle algorithm to randomize questions
    const shuffled = [...QUESTIONS];
    for (let i = shuffled.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
    }
    setQuestions(shuffled);
  }, []);

  // Wait for shuffle to complete
  if (questions.length === 0) return null;

  // Ensure currentIndex is valid
  const currentQuestion = questions[currentIndex];

  const handleAnswer = (score: number) => {
    if (animating) return; // Prevent double clicks

    const newAnswer: Answer = { questionId: currentQuestion.id, score };

    // Create a copy of answers to modify
    const updatedAnswers = [...answers];
    // Update or insert the answer at the current index
    updatedAnswers[currentIndex] = newAnswer;

    setAnswers(updatedAnswers);
    setDirection('forward');
    setAnimating(true);

    setTimeout(() => {
      if (currentIndex < questions.length - 1) {
        setCurrentIndex(prev => prev + 1);
        setAnimating(false);
      } else {
        // Last question - call onComplete
        try {
          onComplete(updatedAnswers);
        } catch (e) {
          console.error("Error completing quiz:", e);
          setAnimating(false); // Restore UI if error occurs
        }
      }
    }, 250);
  };

  const handleBack = () => {
    if (currentIndex > 0 && !animating) {
      setDirection('backward');
      setAnimating(true);
      setTimeout(() => {
        setCurrentIndex(prev => prev - 1);
        setAnimating(false);
      }, 250);
    }
  };

  // Safe progress calculation
  const progress = Math.min(100, Math.round(((currentIndex + 1) / questions.length) * 100));

  return (
    <div className="max-w-4xl mx-auto w-full px-4" role="main" aria-label="מבחן המצפן הפוליטי">
      {/* Progress Bar */}
      <div className="mb-8" role="progressbar" aria-valuenow={progress} aria-valuemin={0} aria-valuemax={100} aria-label="התקדמות במבחן">
        <div className="flex justify-between items-end text-sm text-slate-500 dark:text-slate-400 mb-3 font-medium">
          <div className="flex flex-col">
            <span className="text-xs text-slate-400 dark:text-slate-500 uppercase tracking-wider mb-1">התקדמות</span>
            <span className="text-xl font-bold text-yellow-500 dark:text-yellow-400">שאלה {currentIndex + 1} <span className="text-slate-500 dark:text-slate-600 text-base font-normal">/ {questions.length}</span></span>
          </div>
          <div className="bg-white dark:bg-slate-800 px-3 py-1 rounded-full shadow-sm border border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-300 transition-colors">
             {progress}%
          </div>
        </div>
        <div className="h-4 w-full bg-slate-200 dark:bg-slate-800 rounded-full overflow-hidden border border-slate-300 dark:border-slate-700">
          <div 
            className="h-full bg-yellow-400 transition-all duration-500 ease-out rounded-full shadow-[0_0_10px_rgba(250,204,21,0.5)]"
            style={{ width: `${progress}%` }}
          />
        </div>
      </div>

      {/* Question Card */}
      <div className={`transform transition-all duration-300 ease-out ${
          animating 
            ? (direction === 'forward' ? 'opacity-0 -translate-x-10' : 'opacity-0 translate-x-10') 
            : 'opacity-100 translate-x-0'
        }`}>
        <div className="bg-white/80 dark:bg-slate-900/80 backdrop-blur-xl rounded-3xl shadow-xl p-8 md:p-12 mb-8 border border-slate-200 dark:border-slate-800 min-h-[200px] md:min-h-[240px] flex flex-col justify-center items-center text-center relative overflow-hidden group transition-colors duration-300">
           {/* Subtle background decoration */}
           <div className="absolute top-0 right-0 w-32 h-32 bg-yellow-400/10 dark:bg-yellow-500/5 rounded-bl-full -mr-10 -mt-10 transition-transform group-hover:scale-110"></div>
           <div className="absolute bottom-0 left-0 w-24 h-24 bg-slate-200/50 dark:bg-slate-700/10 rounded-tr-full -ml-8 -mb-8 transition-transform group-hover:scale-110"></div>

           <h2 className="text-2xl md:text-3xl font-bold text-slate-900 dark:text-slate-100 leading-relaxed z-10 transition-colors" role="heading" aria-level={2}>
            {currentQuestion.text}
          </h2>
        </div>

        {/* Answer Buttons */}
        <div className="grid grid-cols-1 md:grid-cols-5 gap-3 md:gap-4 w-full" role="group" aria-label="אפשרויות תשובה">

          {/* Strongly Agree (+2) */}
          <button 
            onClick={() => handleAnswer(2)}
            disabled={animating}
            aria-label="מסכים בהחלט"
            className="group relative h-20 md:h-40 rounded-2xl bg-gradient-to-br from-green-500 to-green-600 text-white hover:from-green-400 hover:to-green-500 transition-all shadow-lg hover:shadow-green-500/25 hover:-translate-y-1 active:scale-95 flex md:flex-col items-center justify-between md:justify-center px-6 md:px-2 gap-2 overflow-hidden border border-green-500 disabled:opacity-50 disabled:cursor-not-allowed disabled:transform-none focus:ring-4 focus:ring-green-400 focus:outline-none"
          >
            <div className="flex md:flex-col items-center gap-2 md:gap-3">
               <Check className="w-6 h-6 md:w-10 md:h-10 stroke-[3]" />
               <span className="text-lg font-bold leading-tight">מסכים<br className="hidden md:block"/> בהחלט</span>
            </div>
          </button>

          {/* Agree (+1) */}
          <button 
            onClick={() => handleAnswer(1)}
            disabled={animating}
            aria-label="מסכים"
            className="group h-16 md:h-40 rounded-2xl bg-green-50 dark:bg-green-900/20 text-green-700 dark:text-green-300 hover:bg-green-100 dark:hover:bg-green-900/30 border-2 border-green-200 dark:border-green-800 hover:border-green-300 transition-all shadow-sm hover:-translate-y-1 active:scale-95 flex md:flex-col items-center justify-between md:justify-center px-6 md:px-2 gap-2 disabled:opacity-50 disabled:cursor-not-allowed disabled:transform-none focus:ring-4 focus:ring-green-300 focus:outline-none"
          >
             <div className="flex md:flex-col items-center gap-2">
                <Check className="w-5 h-5 md:w-6 md:h-6" />
                <span className="font-bold text-base md:text-lg">מסכים</span>
             </div>
          </button>

          {/* Neutral (0) */}
          <button 
            onClick={() => handleAnswer(0)}
            disabled={animating}
            aria-label="ניטרלי"
            className="group h-14 md:h-40 rounded-2xl bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-400 hover:bg-slate-200 dark:hover:bg-slate-700 border-2 border-slate-200 dark:border-slate-700 hover:border-slate-300 transition-all shadow-sm hover:-translate-y-1 active:scale-95 flex md:flex-col items-center justify-between md:justify-center px-6 md:px-2 gap-2 disabled:opacity-50 disabled:cursor-not-allowed disabled:transform-none focus:ring-4 focus:ring-slate-300 focus:outline-none"
          >
             <div className="flex md:flex-col items-center gap-2">
                <Minus className="w-5 h-5 md:w-6 md:h-6" />
                <span className="font-medium text-base md:text-lg">ניטרלי</span>
             </div>
          </button>

          {/* Disagree (-1) */}
          <button 
            onClick={() => handleAnswer(-1)}
            disabled={animating}
            aria-label="לא מסכים"
            className="group h-16 md:h-40 rounded-2xl bg-red-50 dark:bg-red-900/20 text-red-700 dark:text-red-300 hover:bg-red-100 dark:hover:bg-red-900/30 border-2 border-red-200 dark:border-red-800 hover:border-red-300 transition-all shadow-sm hover:-translate-y-1 active:scale-95 flex md:flex-col items-center justify-between md:justify-center px-6 md:px-2 gap-2 disabled:opacity-50 disabled:cursor-not-allowed disabled:transform-none focus:ring-4 focus:ring-red-300 focus:outline-none"
          >
             <div className="flex md:flex-col items-center gap-2">
                <X className="w-5 h-5 md:w-6 md:h-6" />
                <span className="font-bold text-base md:text-lg">לא מסכים</span>
             </div>
          </button>

          {/* Strongly Disagree (-2) */}
          <button 
            onClick={() => handleAnswer(-2)}
            disabled={animating}
            aria-label="מתנגד בהחלט"
            className="group relative h-20 md:h-40 rounded-2xl bg-gradient-to-br from-red-500 to-red-600 text-white hover:from-red-400 hover:to-red-500 transition-all shadow-lg hover:shadow-red-500/25 hover:-translate-y-1 active:scale-95 flex md:flex-col items-center justify-between md:justify-center px-6 md:px-2 gap-2 overflow-hidden border border-red-500 disabled:opacity-50 disabled:cursor-not-allowed disabled:transform-none focus:ring-4 focus:ring-red-400 focus:outline-none"
          >
             <div className="flex md:flex-col items-center gap-2 md:gap-3">
                <X className="w-6 h-6 md:w-10 md:h-10 stroke-[3]" />
                <span className="text-lg font-bold leading-tight">מתנגד<br className="hidden md:block"/> בהחלט</span>
             </div>
          </button>
        </div>

        {/* Navigation Controls */}
        <div className="mt-8 flex justify-center md:justify-start px-2">
            <button
                onClick={handleBack}
                disabled={currentIndex === 0 || animating}
                aria-label="חזור לשאלה הקודמת"
                className={`flex items-center gap-2 px-6 py-3 rounded-xl font-medium transition-all focus:outline-none focus:ring-4 focus:ring-slate-400 ${
                    currentIndex === 0 || animating
                    ? 'text-slate-300 dark:text-slate-700 cursor-not-allowed opacity-50' 
                    : 'text-slate-500 hover:text-yellow-600 dark:text-slate-400 dark:hover:text-yellow-400 hover:bg-slate-100 dark:hover:bg-slate-800'
                }`}
            >
                <ChevronRight className="w-5 h-5 rotate-180" /> 
                <span>חזור לשאלה הקודמת</span>
            </button>
        </div>

      </div>
    </div>
  );
};

export default Quiz;

import React, { useState, useEffect } from 'react';
import Quiz from './components/Quiz';
import ResultView from './components/ResultView';
import ChannelPopup from './components/ChannelPopup';
import AccessibilityMenu from './components/AccessibilityMenu';
import { Answer, Coordinates, AnalysisResult, Axis } from './types';
import { QUESTIONS } from './constants';
import { Compass, History, BrainCircuit, HeartHandshake, Moon, Sun, User, Mail, ArrowLeft, Accessibility, Users } from 'lucide-react';
import { getSavedResult, saveResult, hasSavedResult, getSavedUserDetails } from './utils/storage';

enum AppState {
  WELCOME,
  REGISTRATION,
  QUIZ,
  RESULTS
}

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.WELCOME);
  const [coordinates, setCoordinates] = useState<Coordinates>({ x: 0, y: 0, z: 0 });
  const [friendCoordinates, setFriendCoordinates] = useState<Coordinates | null>(null);
  const [friendName, setFriendName] = useState<string>("");

  const [currentAnalysis, setCurrentAnalysis] = useState<AnalysisResult | null>(null);
  const [hasHistory, setHasHistory] = useState(false);
  const [isDarkMode, setIsDarkMode] = useState(true);
  const [isAccessible, setIsAccessible] = useState(false);
  const [showChannelPopup, setShowChannelPopup] = useState(false);

  // User Data State
  const [userName, setUserName] = useState("");
  const [userEmail, setUserEmail] = useState("");
  const [validationError, setValidationError] = useState(false);

  // Analytics State
  const [startTime, setStartTime] = useState<number>(0);
  const [quizDuration, setQuizDuration] = useState<number>(0);
  const [lastAnswers, setLastAnswers] = useState<Answer[]>([]);

  useEffect(() => {
    setHasHistory(hasSavedResult());

    const savedUser = getSavedUserDetails();
    if (savedUser) {
        setUserName(savedUser.name);
        setUserEmail(savedUser.email);
    }

    const params = new URLSearchParams(window.location.search);
    const xParam = params.get('x');
    const yParam = params.get('y');
    const zParam = params.get('z');

    if (xParam && yParam) {
      const x = parseFloat(xParam);
      const y = parseFloat(yParam);
      const z = zParam ? parseFloat(zParam) : 0;

      if (!isNaN(x) && !isNaN(y)) {
        const coords = { x, y, z };
        setFriendCoordinates(coords);
        setCoordinates(coords);

        const titleParam = params.get('title');
        const descParam = params.get('desc');
        const nameParam = params.get('name');

        if (nameParam) {
            setFriendName(decodeURIComponent(nameParam));
        }

        if (titleParam && descParam) {
          setCurrentAnalysis({
            title: decodeURIComponent(titleParam),
            description: decodeURIComponent(descParam),
            ideology: '',
            economicAnalysis: '',
            nationalAnalysis: '',
            religiousAnalysis: ''
          });
        }

        setAppState(AppState.RESULTS);
      }
    }
  }, []);

  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [isDarkMode]);

  const toggleTheme = () => setIsDarkMode(!isDarkMode);
  const toggleAccessibility = () => setIsAccessible(!isAccessible);

  const calculateResults = (answers: Answer[]) => {
    try {
      const durationSec = (Date.now() - startTime) / 1000;
      setQuizDuration(durationSec);
      setLastAnswers(answers);

      let econScore = 0;
      let nationalScore = 0;
      let socialScore = 0;

      const econQuestionsCount = QUESTIONS.filter(q => q.axis === Axis.ECONOMIC).length || 1;
      const nationalQuestionsCount = QUESTIONS.filter(q => q.axis === Axis.NATIONAL_SECURITY).length || 1;
      // Z-axis aggregates both Social/Cultural and Conservatism questions
      const socialQuestionsCount = QUESTIONS.filter(q => q.axis === Axis.SOCIAL_CULTURAL || q.axis === Axis.CONSERVATISM).length || 1;

      answers.forEach(ans => {
        const question = QUESTIONS.find(q => q.id === ans.questionId);
        if (!question) return;

        const score = Number(ans.score);
        const direction = Number(question.direction);

        if (isNaN(score) || isNaN(direction)) return;

        const impact = score * direction;

        if (question.axis === Axis.ECONOMIC) {
          econScore += impact;
        } else if (question.axis === Axis.NATIONAL_SECURITY) {
          nationalScore += impact;
        } else if (question.axis === Axis.SOCIAL_CULTURAL || question.axis === Axis.CONSERVATISM) {
          socialScore += impact;
        }
      });

      const normalizedX = (econScore / (2 * econQuestionsCount)) * 10;
      const normalizedY = (nationalScore / (2 * nationalQuestionsCount)) * 10;
      const normalizedZ = (socialScore / (2 * socialQuestionsCount)) * 10;

      const safeX = Math.max(-10, Math.min(10, normalizedX || 0));
      const safeY = Math.max(-10, Math.min(10, normalizedY || 0));
      const safeZ = Math.max(-10, Math.min(10, normalizedZ || 0));

      setCoordinates({ x: safeX, y: safeY, z: safeZ });
      setCurrentAnalysis(null);
      setAppState(AppState.RESULTS);

      // Trigger Channel Popup after results are calculated
      setTimeout(() => setShowChannelPopup(true), 2500);

      try {
        window.history.replaceState({}, document.title, window.location.pathname);
      } catch (historyError) {
        console.warn("Could not update history state:", historyError);
      }
    } catch (error) {
      console.error("Error calculating results:", error);
      setAppState(AppState.WELCOME);
    }
  };

  const handleAnalysisComplete = (analysis: AnalysisResult) => {
    saveResult({
      coordinates,
      analysis,
      timestamp: Date.now(),
      userName: userName,
      userEmail: userEmail
    });
    setHasHistory(true);
  };

  const handleLoadHistory = () => {
    const saved = getSavedResult();
    if (saved) {
      setCoordinates(saved.coordinates);
      setCurrentAnalysis(saved.analysis);
      setFriendCoordinates(null);
      setFriendName("");

      if (saved.userName) setUserName(saved.userName);
      if (saved.userEmail) setUserEmail(saved.userEmail || "");

      setAppState(AppState.RESULTS);
    }
  };

  const handleGoToRegistration = () => {
    setAppState(AppState.REGISTRATION);
  };

  const handleStartQuiz = () => {
    if (!userName.trim()) {
      setValidationError(true);
      return;
    }
    setStartTime(Date.now());
    setAppState(AppState.QUIZ);
  };

  const handleRetake = () => {
    try {
      window.history.pushState({}, document.title, window.location.pathname);
    } catch (historyError) {
      console.warn("Could not push history state:", historyError);
    }

    setAppState(AppState.WELCOME);
    setCoordinates({ x: 0, y: 0, z: 0 });
    setFriendCoordinates(null);
    setFriendName("");
    setCurrentAnalysis(null);
    setQuizDuration(0);
    setLastAnswers([]);
    setValidationError(false);
  };

  const isViewingFriendResult = appState === AppState.RESULTS && 
                                friendCoordinates !== null && 
                                coordinates.x === friendCoordinates.x && 
                                coordinates.y === friendCoordinates.y;

  return (
    <div 
      className={`min-h-screen flex flex-col font-sans transition-colors duration-300 ${isAccessible ? 'accessible-mode' : ''}`} 
      dir="rtl"
    >
      {showChannelPopup && <ChannelPopup onClose={() => setShowChannelPopup(false)} />}

      {/* Floating Accessibility Widget */}
      <AccessibilityMenu 
        isHighContrast={isAccessible} 
        toggleHighContrast={toggleAccessibility}
        isDarkMode={isDarkMode}
        toggleTheme={toggleTheme}
      />

      {/* Header */}
      <header className="bg-white/80 dark:bg-slate-900/80 border-b border-slate-200 dark:border-slate-800 sticky top-0 z-50 glass transition-colors duration-300">
        <div className="max-w-6xl mx-auto px-4 h-16 flex items-center justify-between">
          <div 
            className="flex items-center gap-3 cursor-pointer group" 
            onClick={handleRetake}
            tabIndex={0}
          >
            <div className="bg-yellow-400 text-slate-950 p-1.5 rounded-lg shadow-[0_0_15px_rgba(250,204,21,0.3)] group-hover:scale-110 transition-transform">
                <Compass className="w-6 h-6" strokeWidth={2.5} />
            </div>
            <div>
                <h1 className="text-xl font-black tracking-tight leading-none text-slate-900 dark:text-slate-100 text-right">המצפן הפוליטי</h1>
                <span className="text-xs text-yellow-500 dark:text-yellow-400 font-bold tracking-wider block text-right">פרוייקט דעת</span>
            </div>
          </div>

          <div className="flex items-center gap-4">
            <button 
              onClick={toggleTheme} 
              className="p-2 rounded-full hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors text-slate-600 dark:text-slate-400"
              aria-label={isDarkMode ? "החלף למצב יום" : "החלף למצב לילה"}
            >
              {isDarkMode ? <Sun className="w-5 h-5" /> : <Moon className="w-5 h-5" />}
            </button>

            <div className="hidden md:flex items-center gap-2 text-xs font-medium text-slate-500 dark:text-slate-400 bg-slate-100 dark:bg-slate-900/50 px-3 py-1 rounded-full border border-slate-200 dark:border-slate-800">
                <span>פותח ע"י חגי</span>
            </div>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 flex flex-col items-center justify-center py-8 relative overflow-hidden">
        {!isAccessible && (
          <>
            <div className="absolute top-10 left-10 w-96 h-96 bg-yellow-400/20 dark:bg-yellow-500/10 rounded-full filter blur-3xl opacity-30 dark:opacity-20 animate-blob"></div>
            <div className="absolute bottom-10 right-10 w-96 h-96 bg-blue-400/20 dark:bg-slate-700/20 rounded-full filter blur-3xl opacity-30 dark:opacity-20 animate-blob animation-delay-2000"></div>
          </>
        )}

        <div className="z-10 w-full">
            {appState === AppState.WELCOME && (
            <div className="max-w-2xl mx-auto px-4 text-center animate-fadeIn">
                <div className="bg-white/80 dark:bg-slate-900/60 backdrop-blur-xl p-8 md:p-12 rounded-[2.5rem] shadow-2xl border border-slate-200 dark:border-slate-800 relative overflow-hidden ring-1 ring-black/5 dark:ring-white/5 transition-colors duration-300">
                <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-yellow-500 via-yellow-400 to-yellow-500"></div>

                <div className="mb-6 inline-flex items-center justify-center p-4 bg-slate-50 dark:bg-slate-800/50 rounded-2xl shadow-inner border border-slate-100 dark:border-slate-700">
                    <BrainCircuit className="w-12 h-12 text-yellow-500 dark:text-yellow-400" />
                </div>

                <div className="mb-6">
                    <span className="inline-block px-4 py-1.5 bg-yellow-100 dark:bg-yellow-900/30 text-yellow-800 dark:text-yellow-200 text-sm font-black rounded-full border border-yellow-200 dark:border-yellow-700 shadow-sm">
                        🇮🇱 המצפן הפוליטי היחיד בישראל
                    </span>
                </div>

                <h2 className="text-4xl md:text-5xl font-black text-slate-900 dark:text-white mb-6 tracking-tight">
                    גלה את <span className={isAccessible ? "text-yellow-700 dark:text-yellow-300 underline" : "text-transparent bg-clip-text bg-gradient-to-r from-yellow-500 to-yellow-600 dark:from-yellow-200 dark:to-yellow-500"}>הזהות הפוליטית</span> שלך
                </h2>

                <p className="text-lg md:text-xl text-slate-600 dark:text-slate-400 mb-10 leading-relaxed max-w-lg mx-auto font-medium">
                    הצטרף לאלפי ישראלים המשתתפים במחקר של פרוייקט דעת.
                    <br/>
                    האלגוריתם ינתח את עמדותיך ב-49 סוגיות ליבה וימקם אותך במדויק על המפה הפוליטית.
